{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "描いた地図は引き裂いた",
        "世界はあの日のまま",
        "僕はまた",
        "誰かのせいにした",
        "嫌になっちゃうな"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "このまま何かを待ち続けるフリするの",
        "ここから僕はやりなおせますか"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "どこまでも行ける気がした",
        "あの時の僕はどこだ",
        "きっと大人になったとか",
        "そういうことじゃなくてさ",
        "あと少しだけの勇気で",
        "変えられた明日はあった",
        "それさえ気づけなかったんだ"
      ]
    },
    {
      "section": "O1",
      "lyrics": [
        "そんな日はもうたくさんだ",
        "いつまでもなんてないんだ",
        "終わりゆくその前に",
        "一歩踏み出してみた",
        "受け入れながら",
        "祈りながら"
      ]
    }
  ],
