      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "亲手画的 旧地图 撕成两半"
        },
        {
          "id": "V1-02",
          "zh": "世界停在 那一天的原地"
        },
        {
          "id": "V1-03",
          "zh": "而我又一次"
        },
        {
          "id": "V1-04",
          "zh": "把一切 都推给别人"
