          "id": "V1-01",
          "zh": "亲手描绘的地图 被我撕裂"
        },
        {
          "id": "V1-02",
          "zh": "世界停在 那一天的旧模样"
        },
        {
          "id": "V1-03",
          "zh": "而我又一次"
        },
        {
          "id": "V1-04",
          "zh": "把错 都推给旁人"
        },
        {
          "id": "V1-05",
          "zh": "真叫人厌倦 自己"
        }
      ]
    }
